# CP7 Step 7B reconstructed representative real-FCS gating atlas.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","figure_framework.R")); rp_install_and_load(c("dplyr","readr","tibble","ggplot2","patchwork","stringr"),"flowCore"); source(file.path(sd_repo_root(),"R","panels","CP7","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP7"); r<-file.path(a,"11_RData"); out<-file.path(a,"05_flow_figures_flowjo_style_TALL_LAYOUT"); dir.create(out,recursive=TRUE,showWarnings=FALSE); load(file.path(r,"SDY2583_CP7_STEP1_fcs_inventory_marker_QC_RECONSTRUCTED.RData")); load(file.path(r,"SDY2583_CP7_STEP4_composite_scores_RECONSTRUCTED.RData")); reps<-rp_select_representative_subjects(scored_data,CP7_MANIFEST$integrated_score); readr::write_csv(reps,file.path(out,"SDY2583_CP7_representative_samples_RECONSTRUCTED.csv")); plots<-list()
for(i in seq_len(nrow(reps))){sid<-reps$subject_id[i]; group<-as.character(reps$disease_group[i]); path<-fcs_files[grepl(paste0("^",sid,"_CP7"),basename(fcs_files))][1]; obj<-rp_read_transform(path); map<-obj$marker_map; ex<-flowCore::exprs(obj$ff); ch<-c(CD3=rp_find_channel(map,c("^CD3$")),CD8=rp_find_channel(map,c("^CD8$")),CD45RA=rp_find_channel(map,c("CD45RA")),CD62L=rp_find_channel(map,c("CD62L")),CD27=rp_find_channel(map,c("^CD27$")),CD39=rp_find_channel(map,c("CD39")),PD1=rp_find_channel(map,c("PD-?1")),TIGIT=rp_find_channel(map,c("TIGIT")),TIM3=rp_find_channel(map,c("TIM-?3")),LAG3=rp_find_channel(map,c("LAG-?3"))); gate<-rp_vec(ex,ch["CD3"])>2 & rp_vec(ex,ch["CD8"])>2.2; temra<-gate & rp_vec(ex,ch["CD45RA"])>2 & rp_vec(ex,ch["CD62L"])<=2.2
plots[[length(plots)+1]]<-rp_flow_density_plot(ex,ch["CD3"],ch["CD8"],2,2.2,paste(group,sid,"CD3/CD8")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[gate,,drop=FALSE],ch["CD45RA"],ch["CD62L"],2,2.2,paste(group,"CD45RA/CD62L")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[temra,,drop=FALSE],ch["CD27"],ch["CD39"],2,1.5,paste(group,"CD27/CD39 TEMRA")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[gate,,drop=FALSE],ch["PD1"],ch["TIGIT"],1.5,1.5,paste(group,"PD-1/TIGIT")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[gate,,drop=FALSE],ch["TIM3"],ch["LAG3"],1.5,1.5,paste(group,"TIM-3/LAG-3"))}
rp_save_flow_atlas(plots,file.path(out,"FigureS_CP7_representative_checkpoint_gating_RECONSTRUCTED.pdf"),ncol=2,width=9,height=20)
